// Statistical Quality Checks for Data Pipeline
// Performs comprehensive data quality analysis

const items = $input.all();
const config = $('Set Pipeline Parameters').first().json;

// Default thresholds (can be overridden by config)
const thresholds = {
  nullRateThreshold: config.nullRateThreshold || 0.1,
  outlierThreshold: config.outlierThreshold || 1.5,
  minRecords: config.minRecords || 10
};

const results = {
  anomalyDetected: false,
  anomalyType: [],
  affectedColumns: [],
  statistics: {},
  totalRecords: items.length,
  timestamp: new Date().toISOString()
};

// Check minimum records
if (items.length < thresholds.minRecords) {
  results.anomalyDetected = true;
  results.anomalyType.push('INSUFFICIENT_DATA');
  return [results];
}

// Get all column names from first item
const columns = Object.keys(items[0].json);

// Analyze each column
for (const column of columns) {
  const values = items.map(item => item.json[column]);
  const nonNullValues = values.filter(v => v !== null && v !== undefined && v !== '');

  const stats = {
    totalCount: values.length,
    nullCount: values.length - nonNullValues.length,
    nullRate: (values.length - nonNullValues.length) / values.length,
    dataType: typeof nonNullValues[0]
  };

  // Null rate check
  if (stats.nullRate > thresholds.nullRateThreshold) {
    results.anomalyDetected = true;
    if (!results.anomalyType.includes('HIGH_NULL_RATE')) {
      results.anomalyType.push('HIGH_NULL_RATE');
    }
    results.affectedColumns.push(column);
  }

  // Numeric column analysis
  if (stats.dataType === 'number' && nonNullValues.length > 0) {
    const numericValues = nonNullValues.filter(v => typeof v === 'number').sort((a, b) => a - b);

    if (numericValues.length > 0) {
      // Calculate quartiles for IQR method
      const q1Index = Math.floor(numericValues.length * 0.25);
      const q3Index = Math.floor(numericValues.length * 0.75);
      const q1 = numericValues[q1Index];
      const q3 = numericValues[q3Index];
      const iqr = q3 - q1;

      const lowerBound = q1 - (thresholds.outlierThreshold * iqr);
      const upperBound = q3 + (thresholds.outlierThreshold * iqr);

      const outliers = numericValues.filter(v => v < lowerBound || v > upperBound);

      stats.min = Math.min(...numericValues);
      stats.max = Math.max(...numericValues);
      stats.mean = numericValues.reduce((a, b) => a + b, 0) / numericValues.length;
      stats.median = numericValues[Math.floor(numericValues.length / 2)];
      stats.q1 = q1;
      stats.q3 = q3;
      stats.iqr = iqr;
      stats.outlierCount = outliers.length;
      stats.outlierRate = outliers.length / numericValues.length;

      // Outlier detection
      if (stats.outlierRate > 0.05) { // More than 5% outliers
        results.anomalyDetected = true;
        if (!results.anomalyType.includes('OUTLIERS_DETECTED')) {
          results.anomalyType.push('OUTLIERS_DETECTED');
        }
        if (!results.affectedColumns.includes(column)) {
          results.affectedColumns.push(column);
        }
      }
    }
  }

  // String column analysis
  if (stats.dataType === 'string' && nonNullValues.length > 0) {
    const uniqueValues = [...new Set(nonNullValues)];
    stats.uniqueCount = uniqueValues.length;
    stats.uniqueRate = uniqueValues.length / nonNullValues.length;

    // Value distribution
    const distribution = {};
    nonNullValues.forEach(v => {
      distribution[v] = (distribution[v] || 0) + 1;
    });
    stats.topValues = Object.entries(distribution)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5)
      .map(([value, count]) => ({ value, count, percentage: count / nonNullValues.length }));
  }

  results.statistics[column] = stats;
}

// Schema validation - check for unexpected schema changes
if (config.expectedSchema) {
  const expectedColumns = Object.keys(config.expectedSchema);
  const actualColumns = columns;

  const missingColumns = expectedColumns.filter(col => !actualColumns.includes(col));
  const extraColumns = actualColumns.filter(col => !expectedColumns.includes(col));

  if (missingColumns.length > 0 || extraColumns.length > 0) {
    results.anomalyDetected = true;
    if (!results.anomalyType.includes('SCHEMA_MISMATCH')) {
      results.anomalyType.push('SCHEMA_MISMATCH');
    }
    results.schemaMismatch = {
      missingColumns,
      extraColumns
    };
  }
}

return [results];

