// Get the original data from Statistical Quality Checks node
const originalData = $('Run Statistical Quality Checks').all();

// Function to calculate median for numeric arrays
function calculateMedian(arr) {
  const sorted = arr.filter(val => val !== null && val !== undefined).sort((a, b) => a - b);
  if (sorted.length === 0) return 0;
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

// Function to calculate mode for categorical data
function calculateMode(arr) {
  const filtered = arr.filter(val => val !== null && val !== undefined);
  if (filtered.length === 0) return '';
  const frequency = {};
  let maxFreq = 0;
  let mode = filtered[0];

  filtered.forEach(val => {
    frequency[val] = (frequency[val] || 0) + 1;
    if (frequency[val] > maxFreq) {
      maxFreq = frequency[val];
      mode = val;
    }
  });

  return mode;
}

// Function to determine if a value is numeric
function isNumeric(val) {
  return typeof val === 'number' && !isNaN(val);
}

// Analyze data structure and identify columns with nulls
const columnsWithNulls = [];
const columnTypes = {};
const columnValues = {};

if (originalData.length > 0) {
  const sampleItem = originalData[0].json;
  const columns = Object.keys(sampleItem);

  // Collect all values for each column
  columns.forEach(col => {
    columnValues[col] = originalData.map(item => item.json[col]);

    // Check if column has nulls
    const hasNulls = columnValues[col].some(val => val === null || val === undefined);
    if (hasNulls) {
      columnsWithNulls.push(col);
    }

    // Determine column type based on non-null values
    const nonNullValues = columnValues[col].filter(val => val !== null && val !== undefined);
    if (nonNullValues.length > 0) {
      if (nonNullValues.every(val => isNumeric(val))) {
        columnTypes[col] = 'numeric';
      } else if (typeof nonNullValues[0] === 'string') {
        columnTypes[col] = 'text';
      } else {
        columnTypes[col] = 'categorical';
      }
    }
  });
}

// Calculate fill values for each column with nulls
const fillValues = {};
const remediationDetails = [];

columnsWithNulls.forEach(col => {
  if (columnTypes[col] === 'numeric') {
    fillValues[col] = calculateMedian(columnValues[col]);
    remediationDetails.push({
      column: col,
      type: 'numeric',
      fillMethod: 'median',
      fillValue: fillValues[col]
    });
  } else if (columnTypes[col] === 'categorical') {
    fillValues[col] = calculateMode(columnValues[col]);
    remediationDetails.push({
      column: col,
      type: 'categorical',
      fillMethod: 'mode',
      fillValue: fillValues[col]
    });
  } else {
    fillValues[col] = '';
    remediationDetails.push({
      column: col,
      type: 'text',
      fillMethod: 'empty_string',
      fillValue: fillValues[col]
    });
  }
});

// Apply remediation to the data
const remediatedData = originalData.map(item => {
  const newItem = { ...item.json };
  let nullsFixed = 0;

  columnsWithNulls.forEach(col => {
    if (newItem[col] === null || newItem[col] === undefined) {
      newItem[col] = fillValues[col];
      nullsFixed++;
    }
  });

  return {
    json: {
      ...newItem,
      _remediationApplied: true,
      _remediationType: 'fill_nulls',
      _nullsFixed: nullsFixed
    }
  };
});

// Return remediated data with metadata
return [
  {
    json: {
      remediatedData: remediatedData.map(item => item.json),
      remediationApplied: true,
      remediationType: 'fill_nulls',
      columnsRemediated: columnsWithNulls,
      remediationDetails: remediationDetails,
      totalRecords: remediatedData.length,
      timestamp: new Date().toISOString()
    }
  }
];

// Get the original data from Statistical Quality Checks node
const originalData = $('Run Statistical Quality Checks').all();
const remediatedItems = [];
const cappingDetails = [];

// Process each item
for (const item of originalData) {
  const data = item.json;
  const remediatedData = { ...data };

  // Identify numeric columns
  const numericColumns = [];
  for (const key in data) {
    if (typeof data[key] === 'number' && !isNaN(data[key])) {
      numericColumns.push(key);
    }
  }

  // Calculate statistics for each numeric column across all items
  const columnStats = {};

  for (const column of numericColumns) {
    const values = originalData
      .map(item => item.json[column])
      .filter(val => typeof val === 'number' && !isNaN(val))
      .sort((a, b) => a - b);

    if (values.length > 0) {
      // Calculate Q1, Q3, and IQR
      const q1Index = Math.floor(values.length * 0.25);
      const q3Index = Math.floor(values.length * 0.75);

      const q1 = values[q1Index];
      const q3 = values[q3Index];
      const iqr = q3 - q1;

      const lowerBound = q1 - 1.5 * iqr;
      const upperBound = q3 + 1.5 * iqr;

      columnStats[column] = {
        q1,
        q3,
        iqr,
        lowerBound,
        upperBound
      };
    }
  }

  // Cap outliers in the current item
  for (const column of numericColumns) {
    if (columnStats[column]) {
      const originalValue = remediatedData[column];
      const { lowerBound, upperBound } = columnStats[column];

      if (originalValue < lowerBound) {
        remediatedData[column] = lowerBound;
        cappingDetails.push({
          column,
          originalValue,
          cappedValue: lowerBound,
          reason: 'below_lower_bound'
        });
      } else if (originalValue > upperBound) {
        remediatedData[column] = upperBound;
        cappingDetails.push({
          column,
          originalValue,
          cappedValue: upperBound,
          reason: 'above_upper_bound'
        });
      }
    }
  }

  remediatedItems.push({
    json: remediatedData
  });
}

// Return remediated data with metadata
return [{
  json: {
    remediatedData: remediatedItems.map(item => item.json),
    remediationApplied: true,
    remediationType: 'cap_outliers',
    cappingDetails: cappingDetails,
    totalItemsProcessed: remediatedItems.length,
    totalValuesCapped: cappingDetails.length,
    timestamp: new Date().toISOString()
  }
}];

// Get original data from Statistical Quality Checks node
const originalData = $('Run Statistical Quality Checks').all();
const remediationPlan = $json;

// Helper function to convert value to appropriate type
function convertToType(value, targetType) {
  if (value === null || value === undefined) {
    return getDefaultForType(targetType);
  }

  switch(targetType) {
    case 'number':
      const num = Number(value);
      return isNaN(num) ? 0 : num;

    case 'string':
      return String(value);

    case 'boolean':
      if (typeof value === 'boolean') return value;
      if (typeof value === 'string') {
        return value.toLowerCase() === 'true' || value === '1';
      }
      return Boolean(value);

    case 'date':
      const date = new Date(value);
      return isNaN(date.getTime()) ? new Date().toISOString() : date.toISOString();

    default:
      return value;
  }
}

// Helper function to get default value for type
function getDefaultForType(type) {
  switch(type) {
    case 'number': return 0;
    case 'string': return '';
    case 'boolean': return false;
    case 'date': return new Date().toISOString();
    default: return null;
  }
}

// Expected schema definition (can be customized based on your data)
const expectedSchema = {
  id: 'number',
  timestamp: 'date',
  value: 'number',
  status: 'string',
  is_active: 'boolean',
  metric_name: 'string',
  count: 'number'
};

// Process each item and reformat according to schema
const remediatedItems = originalData.map(item => {
  const data = item.json;
  const reformattedData = {};
  const schemaChanges = [];

  // Apply expected schema
  for (const [field, expectedType] of Object.entries(expectedSchema)) {
    if (!(field in data)) {
      // Missing column - add with default
      reformattedData[field] = getDefaultForType(expectedType);
      schemaChanges.push(`Added missing field '${field}' with default value`);
    } else {
      const originalValue = data[field];
      const originalType = typeof originalValue;

      // Convert to expected type
      reformattedData[field] = convertToType(originalValue, expectedType);

      // Track if conversion happened
      if (originalType !== expectedType && originalValue !== null) {
        schemaChanges.push(`Converted '${field}' from ${originalType} to ${expectedType}`);
      }
    }
  }

  // Preserve any additional fields not in schema
  for (const [field, value] of Object.entries(data)) {
    if (!(field in expectedSchema)) {
      reformattedData[field] = value;
    }
  }

  return {
    json: {
      ...reformattedData,
      remediationApplied: true,
      remediationType: 'schema_reformat',
      schemaChanges: schemaChanges,
      originalData: data,
      remediatedAt: new Date().toISOString()
    }
  };
});

return remediatedItems;

// Retry fetching data from upstream source
// This would re-execute the Fetch Latest Data Batch query or call the upstream API

const items = $input.all();
const remediationPlan = items[0].json;

// Simulate retry logic - in production, this would actually re-execute the upstream fetch
// For now, we'll create a placeholder structure showing the retry attempt

const retryResult = {
  remediationApplied: true,
  remediationType: 'retry_upstream',
  retryDetails: {
    attemptNumber: 1,
    maxRetries: 3,
    retryTimestamp: new Date().toISOString(),
    upstreamSource: 'Fetch Latest Data Batch',
    status: 'retry_initiated'
  },
  originalAnomalies: remediationPlan.anomalies || [],
  message: 'Upstream data fetch retry initiated. In production, this would re-execute the data fetch operation.'
};

// In a real implementation, you would:
// 1. Re-execute the upstream query/API call
// 2. Validate the new data
// 3. Compare with previous results
// 4. Return the fresh data with retry metadata

return [retryResult];

// Merge all remediated data from different remediation branches
// Combine with original anomaly classification and remediation plan
// Preserve all metadata including action taken, parameters used, and original statistics

const remediatedItems = [];

// Process all input items from different remediation branches
for (const item of $input.all()) {
  const mergedData = {
    // Original data from the item
    remediatedData: item.json.remediatedData || item.json.data || item.json,

    // Preserve anomaly classification from earlier in the workflow
    anomalyClassification: item.json.anomalyClassification || {
      type: item.json.anomalyType,
      severity: item.json.severity,
      confidence: item.json.confidence,
      description: item.json.anomalyDescription
    },

    // Preserve remediation plan
    remediationPlan: item.json.remediationPlan || {
      action: item.json.action,
      strategy: item.json.strategy,
      reasoning: item.json.reasoning
    },

    // Metadata about the remediation execution
    metadata: {
      actionTaken: item.json.actionTaken || item.json.action,
      parametersUsed: item.json.parametersUsed || item.json.parameters || {},
      originalStatistics: item.json.originalStatistics || item.json.statistics || {},
      remediationTimestamp: new Date().toISOString(),
      remediationBranch: item.json.remediationBranch || 'unknown',
      recordsProcessed: item.json.recordsProcessed || 0,
      recordsModified: item.json.recordsModified || 0
    },

    // Preserve any additional fields
    ...item.json
  };

  remediatedItems.push(mergedData);
}

// Return merged results
return remediatedItems.map(item => ({ json: item }));

// Re-run Quality Checks on Remediated Data
// This validates whether the remediation was successful

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json.remediatedData || item.json.data || item.json;

  // Initialize quality check results
  const qualityChecks = {
    nullCheck: { passed: true, issues: [] },
    outlierCheck: { passed: true, issues: [] },
    schemaCheck: { passed: true, issues: [] },
    rangeCheck: { passed: true, issues: [] }
  };

  let totalIssues = 0;

  // Check for null/missing values
  if (Array.isArray(data)) {
    data.forEach((record, idx) => {
      Object.entries(record).forEach(([key, value]) => {
        if (value === null || value === undefined || value === '') {
          qualityChecks.nullCheck.passed = false;
          qualityChecks.nullCheck.issues.push(`Null value in record ${idx}, field: ${key}`);
          totalIssues++;
        }
      });
    });
  } else {
    Object.entries(data).forEach(([key, value]) => {
      if (value === null || value === undefined || value === '') {
        qualityChecks.nullCheck.passed = false;
        qualityChecks.nullCheck.issues.push(`Null value in field: ${key}`);
        totalIssues++;
      }
    });
  }

  // Check for outliers in numeric fields
  const numericFields = [];
  const dataArray = Array.isArray(data) ? data : [data];

  dataArray.forEach(record => {
    Object.entries(record).forEach(([key, value]) => {
      if (typeof value === 'number' && !isNaN(value)) {
        if (!numericFields[key]) numericFields[key] = [];
        numericFields[key].push(value);
      }
    });
  });

  Object.entries(numericFields).forEach(([field, values]) => {
    if (values.length > 2) {
      const mean = values.reduce((a, b) => a + b, 0) / values.length;
      const variance = values.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) / values.length;
      const stdDev = Math.sqrt(variance);

      values.forEach((value, idx) => {
        const zScore = Math.abs((value - mean) / stdDev);
        if (zScore > 3) {
          qualityChecks.outlierCheck.passed = false;
          qualityChecks.outlierCheck.issues.push(`Outlier detected in ${field}: ${value} (z-score: ${zScore.toFixed(2)})`);
          totalIssues++;
        }
      });
    }
  });

  // Check for schema consistency
  if (Array.isArray(data) && data.length > 1) {
    const firstKeys = Object.keys(data[0]).sort();
    data.forEach((record, idx) => {
      const currentKeys = Object.keys(record).sort();
      if (JSON.stringify(firstKeys) !== JSON.stringify(currentKeys)) {
        qualityChecks.schemaCheck.passed = false;
        qualityChecks.schemaCheck.issues.push(`Schema mismatch in record ${idx}`);
        totalIssues++;
      }
    });
  }

  // Determine if remediation was successful
  const remediationSuccessful = totalIssues === 0 && 
    qualityChecks.nullCheck.passed && 
    qualityChecks.outlierCheck.passed && 
    qualityChecks.schemaCheck.passed;

  results.push({
    json: {
      ...item.json,
      qualityCheckResults: qualityChecks,
      totalIssuesFound: totalIssues,
      remediationSuccessful: remediationSuccessful,
      checkTimestamp: new Date().toISOString(),
      status: remediationSuccessful ? 'PASSED' : 'FAILED'
    }
  });
}

return results;

