// Compare current data batch with historical baseline metrics
// Calculate deviation percentages for key metrics
// Flag significant changes that may indicate data quality issues

const currentData = $('Run Statistical Quality Checks').first().json;
const historicalBaseline = $('Fetch Historical Baseline Data').all();

// Initialize comparison results
const comparisonResults = {
  timestamp: new Date().toISOString(),
  significantDeviations: false,
  deviationFlags: [],
  metrics: {}
};

// Helper function to calculate percentage deviation
function calculateDeviation(current, baseline) {
  if (baseline === 0) return current === 0 ? 0 : 100;
  return ((current - baseline) / baseline) * 100;
}

// Helper function to determine if deviation is significant
function isSignificantDeviation(deviation, threshold = 20) {
  return Math.abs(deviation) > threshold;
}

// Extract baseline metrics from historical data
let baselineMetrics = {};
if (historicalBaseline.length > 0) {
  // Calculate average baseline metrics from historical data
  const historicalStats = historicalBaseline.map(item => item.json);

  // Average null rates across historical data
  const avgNullRates = {};
  const avgOutlierCounts = {};
  const avgRecordVolumes = [];

  historicalStats.forEach(stat => {
    if (stat.statistics) {
      Object.entries(stat.statistics).forEach(([column, stats]) => {
        if (!avgNullRates[column]) avgNullRates[column] = [];
        if (!avgOutlierCounts[column]) avgOutlierCounts[column] = [];

        if (stats.nullRate !== undefined) {
          avgNullRates[column].push(stats.nullRate);
        }
        if (stats.outlierCount !== undefined) {
          avgOutlierCounts[column].push(stats.outlierCount);
        }
      });
    }
    if (stat.totalRecords) {
      avgRecordVolumes.push(stat.totalRecords);
    }
  });

  // Calculate baseline averages
  baselineMetrics.nullRates = {};
  Object.entries(avgNullRates).forEach(([column, rates]) => {
    baselineMetrics.nullRates[column] = rates.reduce((a, b) => a + b, 0) / rates.length;
  });

  baselineMetrics.outlierCounts = {};
  Object.entries(avgOutlierCounts).forEach(([column, counts]) => {
    baselineMetrics.outlierCounts[column] = counts.reduce((a, b) => a + b, 0) / counts.length;
  });

  baselineMetrics.avgRecordVolume = avgRecordVolumes.length > 0 
    ? avgRecordVolumes.reduce((a, b) => a + b, 0) / avgRecordVolumes.length 
    : 0;
} else {
  // No historical baseline available - use current as baseline
  baselineMetrics.nullRates = {};
  baselineMetrics.outlierCounts = {};
  baselineMetrics.avgRecordVolume = currentData.totalRecords || 0;

  if (currentData.statistics) {
    Object.entries(currentData.statistics).forEach(([column, stats]) => {
      baselineMetrics.nullRates[column] = stats.nullRate || 0;
      baselineMetrics.outlierCounts[column] = stats.outlierCount || 0;
    });
  }
}

// Compare record volume
const currentRecordVolume = currentData.totalRecords || 0;
const volumeDeviation = calculateDeviation(currentRecordVolume, baselineMetrics.avgRecordVolume);

comparisonResults.metrics.recordVolume = {
  current: currentRecordVolume,
  baseline: baselineMetrics.avgRecordVolume,
  deviation: volumeDeviation,
  deviationPercentage: `${volumeDeviation.toFixed(2)}%`,
  isSignificant: isSignificantDeviation(volumeDeviation)
};

if (isSignificantDeviation(volumeDeviation)) {
  comparisonResults.significantDeviations = true;
  comparisonResults.deviationFlags.push({
    metric: 'record_volume',
    deviation: volumeDeviation,
    message: `Record volume deviated by ${volumeDeviation.toFixed(2)}% from baseline`
  });
}

// Compare null rates per column
comparisonResults.metrics.nullRates = {};
if (currentData.statistics) {
  Object.entries(currentData.statistics).forEach(([column, stats]) => {
    const currentNullRate = stats.nullRate || 0;
    const baselineNullRate = baselineMetrics.nullRates[column] || 0;
    const nullRateDeviation = calculateDeviation(currentNullRate, baselineNullRate);

    comparisonResults.metrics.nullRates[column] = {
      current: currentNullRate,
      baseline: baselineNullRate,
      deviation: nullRateDeviation,
      deviationPercentage: `${nullRateDeviation.toFixed(2)}%`,
      isSignificant: isSignificantDeviation(nullRateDeviation, 30) // 30% threshold for null rates
    };

    if (isSignificantDeviation(nullRateDeviation, 30)) {
      comparisonResults.significantDeviations = true;
      comparisonResults.deviationFlags.push({
        metric: 'null_rate',
        column: column,
        deviation: nullRateDeviation,
        message: `Null rate in column '${column}' deviated by ${nullRateDeviation.toFixed(2)}% from baseline`
      });
    }
  });
}

// Compare outlier counts per column
comparisonResults.metrics.outlierCounts = {};
if (currentData.statistics) {
  Object.entries(currentData.statistics).forEach(([column, stats]) => {
    if (stats.outlierCount !== undefined) {
      const currentOutlierCount = stats.outlierCount || 0;
      const baselineOutlierCount = baselineMetrics.outlierCounts[column] || 0;
      const outlierDeviation = calculateDeviation(currentOutlierCount, baselineOutlierCount);

      comparisonResults.metrics.outlierCounts[column] = {
        current: currentOutlierCount,
        baseline: baselineOutlierCount,
        deviation: outlierDeviation,
        deviationPercentage: `${outlierDeviation.toFixed(2)}%`,
        isSignificant: isSignificantDeviation(outlierDeviation, 50) // 50% threshold for outliers
      };

      if (isSignificantDeviation(outlierDeviation, 50)) {
        comparisonResults.significantDeviations = true;
        comparisonResults.deviationFlags.push({
          metric: 'outlier_count',
          column: column,
          deviation: outlierDeviation,
          message: `Outlier count in column '${column}' deviated by ${outlierDeviation.toFixed(2)}% from baseline`
        });
      }
    }
  });
}

// Add summary statistics
comparisonResults.summary = {
  totalDeviations: comparisonResults.deviationFlags.length,
  hasSignificantChanges: comparisonResults.significantDeviations,
  baselineDataPoints: historicalBaseline.length,
  comparisonTimestamp: new Date().toISOString()
};

return [{ json: comparisonResults }];

// Trend Analysis on Historical Data
// Calculates moving averages, trend direction, seasonal patterns, and velocity of change

const currentData = $('Run Statistical Quality Checks').first().json;
const historicalData = $('Fetch Historical Baseline Data').all();
const comparisonData = $('Compare with Historical Baseline').first().json;

// Helper function to calculate moving average
function calculateMovingAverage(data, windowSize) {
  const result = [];
  for (let i = 0; i < data.length; i++) {
    if (i < windowSize - 1) {
      result.push(null);
      continue;
    }
    const window = data.slice(i - windowSize + 1, i + 1);
    const avg = window.reduce((sum, val) => sum + val, 0) / windowSize;
    result.push(avg);
  }
  return result;
}

// Helper function to detect trend direction
function detectTrendDirection(values) {
  if (values.length < 2) return 'insufficient_data';

  const recentValues = values.slice(-10); // Last 10 data points
  const firstHalf = recentValues.slice(0, Math.floor(recentValues.length / 2));
  const secondHalf = recentValues.slice(Math.floor(recentValues.length / 2));

  const firstAvg = firstHalf.reduce((sum, val) => sum + val, 0) / firstHalf.length;
  const secondAvg = secondHalf.reduce((sum, val) => sum + val, 0) / secondHalf.length;

  const percentChange = ((secondAvg - firstAvg) / firstAvg) * 100;

  if (Math.abs(percentChange) < 5) return 'stable';
  if (percentChange > 0) return 'improving';
  return 'degrading';
}

// Helper function to calculate velocity of change
function calculateVelocity(values) {
  if (values.length < 2) return 0;

  const changes = [];
  for (let i = 1; i < values.length; i++) {
    changes.push(values[i] - values[i - 1]);
  }

  const avgChange = changes.reduce((sum, val) => sum + val, 0) / changes.length;
  return avgChange;
}

// Helper function to detect seasonal patterns
function detectSeasonalPatterns(values, period = 7) {
  if (values.length < period * 2) return { hasPattern: false, strength: 0 };

  const seasonalAverages = [];
  for (let i = 0; i < period; i++) {
    const periodValues = [];
    for (let j = i; j < values.length; j += period) {
      periodValues.push(values[j]);
    }
    const avg = periodValues.reduce((sum, val) => sum + val, 0) / periodValues.length;
    seasonalAverages.push(avg);
  }

  const overallAvg = values.reduce((sum, val) => sum + val, 0) / values.length;
  const variance = seasonalAverages.reduce((sum, val) => sum + Math.pow(val - overallAvg, 2), 0) / seasonalAverages.length;
  const strength = Math.sqrt(variance) / overallAvg;

  return {
    hasPattern: strength > 0.1,
    strength: strength,
    pattern: seasonalAverages
  };
}

// Extract time series data from historical baseline
const timeSeriesData = {};
const affectedColumns = currentData.affectedColumns || [];

if (historicalData && historicalData.length > 0) {
  // Process each affected column
  affectedColumns.forEach(column => {
    const values = historicalData
      .map(item => item.json[column])
      .filter(val => typeof val === 'number' && !isNaN(val));

    if (values.length > 0) {
      timeSeriesData[column] = values;
    }
  });
}

// Perform trend analysis for each column
const trendAnalysis = {};

Object.entries(timeSeriesData).forEach(([column, values]) => {
  const ma7 = calculateMovingAverage(values, 7);
  const ma30 = calculateMovingAverage(values, 30);
  const trendDirection = detectTrendDirection(values);
  const velocity = calculateVelocity(values);
  const seasonality = detectSeasonalPatterns(values, 7);

  // Calculate prediction for next value
  const recentValues = values.slice(-5);
  const recentAvg = recentValues.reduce((sum, val) => sum + val, 0) / recentValues.length;
  const prediction = recentAvg + velocity;

  trendAnalysis[column] = {
    currentValue: values[values.length - 1],
    movingAverage7: ma7[ma7.length - 1],
    movingAverage30: ma30[ma30.length - 1],
    trendDirection: trendDirection,
    velocity: velocity,
    velocityPercentage: (velocity / recentAvg) * 100,
    seasonality: seasonality,
    prediction: prediction,
    predictionConfidence: seasonality.hasPattern ? 'medium' : 'low',
    dataPoints: values.length
  };
});

// Overall trend assessment
const trendDirections = Object.values(trendAnalysis).map(t => t.trendDirection);
const degradingCount = trendDirections.filter(d => d === 'degrading').length;
const improvingCount = trendDirections.filter(d => d === 'improving').length;

let overallTrend = 'stable';
if (degradingCount > improvingCount) {
  overallTrend = 'degrading';
} else if (improvingCount > degradingCount) {
  overallTrend = 'improving';
}

const result = {
  trendAnalysis: trendAnalysis,
  overallTrend: overallTrend,
  summary: {
    totalColumnsAnalyzed: Object.keys(trendAnalysis).length,
    degradingColumns: degradingCount,
    improvingColumns: improvingCount,
    stableColumns: trendDirections.filter(d => d === 'stable').length
  },
  recommendations: [],
  timestamp: new Date().toISOString()
};

// Generate recommendations based on trends
if (overallTrend === 'degrading') {
  result.recommendations.push('Data quality is degrading. Consider investigating upstream data sources.');
}

Object.entries(trendAnalysis).forEach(([column, analysis]) => {
  if (analysis.trendDirection === 'degrading' && Math.abs(analysis.velocityPercentage) > 10) {
    result.recommendations.push(`Column '${column}' is degrading rapidly (${analysis.velocityPercentage.toFixed(2)}% change rate). Immediate attention required.`);
  }

  if (analysis.seasonality.hasPattern && analysis.seasonality.strength > 0.2) {
    result.recommendations.push(`Column '${column}' shows strong seasonal patterns. Consider time-based adjustments.`);
  }
});

return [result];

