// Generate Comprehensive Remediation Report
// Aggregates incident data and produces structured analytics

const items = $input.all();

// Initialize report structure
const report = {
  reportMetadata: {
    generatedAt: new Date().toISOString(),
    reportPeriod: 'last_15_minutes',
    totalIncidents: items.length
  },
  summaryStatistics: {
    totalIncidents: items.length,
    successfulRemediations: 0,
    failedRemediations: 0,
    successRate: 0,
    averageConfidence: 0,
    criticalIncidents: 0,
    highSeverityIncidents: 0,
    mediumSeverityIncidents: 0,
    lowSeverityIncidents: 0
  },
  breakdownByAnomalyType: {},
  breakdownBySeverity: {},
  breakdownByAction: {},
  topIssues: [],
  affectedColumnsFrequency: {},
  trendAnalysis: {
    anomalyRateChange: 0,
    successRateChange: 0,
    mostCommonAnomalyType: '',
    emergingPatterns: []
  },
  recommendations: []
};

// Process each incident
let totalConfidence = 0;
const anomalyTypeCounts = {};
const severityCounts = { critical: 0, high: 0, medium: 0, low: 0 };
const actionCounts = {};
const columnFrequency = {};
const issueDetails = [];

for (const item of items) {
  const data = item.json;

  // Count successes and failures
  if (data.remediation_successful === true || data.remediationSuccessful === true) {
    report.summaryStatistics.successfulRemediations++;
  } else {
    report.summaryStatistics.failedRemediations++;
  }

  // Aggregate confidence scores
  const confidence = data.classification_confidence || data.confidence || 0;
  totalConfidence += confidence;

  // Count by anomaly type
  const anomalyType = data.anomaly_type || data.classification || 'unknown';
  anomalyTypeCounts[anomalyType] = (anomalyTypeCounts[anomalyType] || 0) + 1;

  // Count by severity
  const severity = (data.severity || 'medium').toLowerCase();
  severityCounts[severity] = (severityCounts[severity] || 0) + 1;

  if (severity === 'critical') report.summaryStatistics.criticalIncidents++;
  if (severity === 'high') report.summaryStatistics.highSeverityIncidents++;
  if (severity === 'medium') report.summaryStatistics.mediumSeverityIncidents++;
  if (severity === 'low') report.summaryStatistics.lowSeverityIncidents++;

  // Count by action taken
  const action = data.action_taken || data.action || 'unknown';
  actionCounts[action] = (actionCounts[action] || 0) + 1;

  // Track affected columns
  let affectedColumns = [];
  if (typeof data.affected_columns === 'string') {
    try {
      affectedColumns = JSON.parse(data.affected_columns);
    } catch (e) {
      affectedColumns = data.affected_columns.split(',').map(c => c.trim());
    }
  } else if (Array.isArray(data.affected_columns)) {
    affectedColumns = data.affected_columns;
  }

  affectedColumns.forEach(col => {
    columnFrequency[col] = (columnFrequency[col] || 0) + 1;
  });

  // Collect issue details for top issues analysis
  issueDetails.push({
    anomalyType,
    severity,
    action,
    affectedColumns,
    successful: data.remediation_successful || data.remediationSuccessful || false,
    confidence,
    timestamp: data.timestamp || new Date().toISOString()
  });
}

// Calculate summary statistics
report.summaryStatistics.successRate = items.length > 0 
  ? (report.summaryStatistics.successfulRemediations / items.length * 100).toFixed(2) 
  : 0;
report.summaryStatistics.averageConfidence = items.length > 0 
  ? (totalConfidence / items.length).toFixed(2) 
  : 0;

// Build breakdown by anomaly type
for (const [type, count] of Object.entries(anomalyTypeCounts)) {
  const typeItems = issueDetails.filter(i => i.anomalyType === type);
  const successCount = typeItems.filter(i => i.successful).length;

  report.breakdownByAnomalyType[type] = {
    count,
    percentage: ((count / items.length) * 100).toFixed(2),
    successRate: typeItems.length > 0 ? ((successCount / typeItems.length) * 100).toFixed(2) : 0,
    successCount,
    failureCount: typeItems.length - successCount
  };
}

// Build breakdown by severity
for (const [severity, count] of Object.entries(severityCounts)) {
  if (count > 0) {
    const severityItems = issueDetails.filter(i => i.severity.toLowerCase() === severity);
    const successCount = severityItems.filter(i => i.successful).length;

    report.breakdownBySeverity[severity] = {
      count,
      percentage: ((count / items.length) * 100).toFixed(2),
      successRate: severityItems.length > 0 ? ((successCount / severityItems.length) * 100).toFixed(2) : 0
    };
  }
}

// Build breakdown by action
for (const [action, count] of Object.entries(actionCounts)) {
  const actionItems = issueDetails.filter(i => i.action === action);
  const successCount = actionItems.filter(i => i.successful).length;

  report.breakdownByAction[action] = {
    count,
    percentage: ((count / items.length) * 100).toFixed(2),
    successRate: actionItems.length > 0 ? ((successCount / actionItems.length) * 100).toFixed(2) : 0,
    successCount,
    failureCount: actionItems.length - successCount
  };
}

// Identify top issues (most frequent affected columns)
report.topIssues = Object.entries(columnFrequency)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([column, frequency]) => ({
    column,
    frequency,
    percentage: ((frequency / items.length) * 100).toFixed(2)
  }));

report.affectedColumnsFrequency = columnFrequency;

// Trend analysis
const mostCommonType = Object.entries(anomalyTypeCounts)
  .sort((a, b) => b[1] - a[1])[0];
report.trendAnalysis.mostCommonAnomalyType = mostCommonType ? mostCommonType[0] : 'none';

// Identify emerging patterns
if (report.summaryStatistics.criticalIncidents > 0) {
  report.trendAnalysis.emergingPatterns.push('Critical incidents detected - immediate attention required');
}
if (parseFloat(report.summaryStatistics.successRate) < 70) {
  report.trendAnalysis.emergingPatterns.push('Low remediation success rate - review remediation strategies');
}
if (report.topIssues.length > 0 && report.topIssues[0].frequency > items.length * 0.5) {
  report.trendAnalysis.emergingPatterns.push(`High concentration of issues in column: ${report.topIssues[0].column}`);
}

// Generate recommendations
if (parseFloat(report.summaryStatistics.successRate) < 80) {
  report.recommendations.push({
    priority: 'high',
    category: 'remediation_strategy',
    recommendation: 'Review and optimize remediation strategies - success rate below 80%',
    actionItems: [
      'Analyze failed remediation attempts',
      'Consider adding new remediation patterns',
      'Review threshold configurations'
    ]
  });
}

if (report.summaryStatistics.criticalIncidents > 0) {
  report.recommendations.push({
    priority: 'critical',
    category: 'incident_response',
    recommendation: `${report.summaryStatistics.criticalIncidents} critical incidents require immediate attention`,
    actionItems: [
      'Review critical incidents immediately',
      'Escalate to senior data engineers',
      'Consider implementing additional monitoring'
    ]
  });
}

if (report.topIssues.length > 0) {
  const topColumn = report.topIssues[0];
  if (topColumn.frequency > 3) {
    report.recommendations.push({
      priority: 'medium',
      category: 'data_quality',
      recommendation: `Column '${topColumn.column}' frequently affected - investigate upstream data source`,
      actionItems: [
        `Review data source for column: ${topColumn.column}`,
        'Check for schema changes or data type issues',
        'Consider adding validation at ingestion layer'
      ]
    });
  }
}

const failedActions = Object.entries(report.breakdownByAction)
  .filter(([action, stats]) => parseFloat(stats.successRate) < 50);

if (failedActions.length > 0) {
  failedActions.forEach(([action, stats]) => {
    report.recommendations.push({
      priority: 'medium',
      category: 'remediation_action',
      recommendation: `Action '${action}' has low success rate (${stats.successRate}%) - needs improvement`,
      actionItems: [
        `Review implementation of ${action} remediation`,
        'Analyze failure patterns',
        'Consider alternative remediation approaches'
      ]
    });
  });
}

if (parseFloat(report.summaryStatistics.averageConfidence) < 70) {
  report.recommendations.push({
    priority: 'low',
    category: 'classification',
    recommendation: 'Low average classification confidence - consider model retraining or threshold adjustment',
    actionItems: [
      'Review classification model performance',
      'Collect more training data for edge cases',
      'Adjust confidence thresholds'
    ]
  });
}

// Add metrics export format
report.metricsExport = {
  timestamp: new Date().toISOString(),
  metrics: [
    { name: 'data_pipeline.incidents.total', value: items.length, type: 'count' },
    { name: 'data_pipeline.remediation.success_rate', value: parseFloat(report.summaryStatistics.successRate), type: 'percentage' },
    { name: 'data_pipeline.remediation.successful', value: report.summaryStatistics.successfulRemediations, type: 'count' },
    { name: 'data_pipeline.remediation.failed', value: report.summaryStatistics.failedRemediations, type: 'count' },
    { name: 'data_pipeline.incidents.critical', value: report.summaryStatistics.criticalIncidents, type: 'count' },
    { name: 'data_pipeline.incidents.high', value: report.summaryStatistics.highSeverityIncidents, type: 'count' },
    { name: 'data_pipeline.classification.avg_confidence', value: parseFloat(report.summaryStatistics.averageConfidence), type: 'percentage' }
  ]
};

// Add anomaly type metrics
for (const [type, stats] of Object.entries(report.breakdownByAnomalyType)) {
  report.metricsExport.metrics.push({
    name: `data_pipeline.anomaly.${type}.count`,
    value: stats.count,
    type: 'count'
  });
  report.metricsExport.metrics.push({
    name: `data_pipeline.anomaly.${type}.success_rate`,
    value: parseFloat(stats.successRate),
    type: 'percentage'
  });
}

return [{ json: report }];

// ML-Based Anomaly Scoring using Isolation Forest Algorithm
// Combines multiple features: deviation from baseline, trend velocity, historical patterns, and statistical outliers

const currentData = $('Run Statistical Quality Checks').first().json;
const baselineData = $('Compare with Historical Baseline').first().json;
const trendData = $('Calculate Trend Analysis Metrics').first().json;

// Helper function to normalize values to 0-1 range
function normalize(value, min, max) {
  if (max === min) return 0;
  return (value - min) / (max - min);
}

// Helper function to calculate isolation score for a single feature
function calculateIsolationScore(value, dataset) {
  if (!dataset || dataset.length === 0) return 0;

  const sorted = [...dataset].sort((a, b) => a - b);
  const n = sorted.length;

  // Find position of value in sorted array
  let position = 0;
  for (let i = 0; i < n; i++) {
    if (sorted[i] >= value) {
      position = i;
      break;
    }
  }

  // Calculate isolation score based on position
  // Values at extremes get higher scores
  const distanceFromMedian = Math.abs(position - n / 2);
  const maxDistance = n / 2;
  return distanceFromMedian / maxDistance;
}

// Feature 1: Deviation from Baseline Score
function calculateBaselineDeviationScore() {
  if (!baselineData || !baselineData.baseline) return 0;

  const deviations = [];
  const stats = currentData.statistics || {};
  const baseline = baselineData.baseline || {};

  for (const column in stats) {
    if (stats[column].mean !== undefined && baseline[column]?.mean !== undefined) {
      const deviation = Math.abs(stats[column].mean - baseline[column].mean);
      const baselineStdDev = baseline[column].stdDev || 1;
      const normalizedDeviation = deviation / baselineStdDev;
      deviations.push(normalizedDeviation);
    }
  }

  if (deviations.length === 0) return 0;

  // Average deviation score
  const avgDeviation = deviations.reduce((a, b) => a + b, 0) / deviations.length;
  return Math.min(avgDeviation / 3, 1); // Normalize to 0-1, 3 std devs = max
}

// Feature 2: Trend Velocity Score
function calculateTrendVelocityScore() {
  if (!trendData || !trendData.velocity) return 0;

  const velocity = trendData.velocity || 0;
  const historicalVelocities = trendData.historicalVelocities || [velocity];

  // Calculate how unusual the current velocity is
  const isolationScore = calculateIsolationScore(Math.abs(velocity), historicalVelocities.map(Math.abs));

  return isolationScore;
}

// Feature 3: Historical Pattern Score
function calculateHistoricalPatternScore() {
  if (!baselineData || !baselineData.historicalPatterns) return 0;

  const patterns = baselineData.historicalPatterns || {};
  const currentPattern = currentData.pattern || 'unknown';

  // Check if current pattern matches historical patterns
  const patternFrequency = patterns[currentPattern] || 0;
  const totalPatterns = Object.values(patterns).reduce((a, b) => a + b, 0) || 1;
  const patternProbability = patternFrequency / totalPatterns;

  // Lower probability = higher anomaly score
  return 1 - patternProbability;
}

// Feature 4: Statistical Outlier Score
function calculateStatisticalOutlierScore() {
  const stats = currentData.statistics || {};
  const outlierScores = [];

  for (const column in stats) {
    if (stats[column].outlierRate !== undefined) {
      outlierScores.push(stats[column].outlierRate);
    }
  }

  if (outlierScores.length === 0) return 0;

  // Average outlier rate across all columns
  const avgOutlierRate = outlierScores.reduce((a, b) => a + b, 0) / outlierScores.length;
  return Math.min(avgOutlierRate * 10, 1); // Scale up and cap at 1
}

// Feature 5: Null Rate Score
function calculateNullRateScore() {
  const stats = currentData.statistics || {};
  const nullRates = [];

  for (const column in stats) {
    if (stats[column].nullRate !== undefined) {
      nullRates.push(stats[column].nullRate);
    }
  }

  if (nullRates.length === 0) return 0;

  // Average null rate across all columns
  const avgNullRate = nullRates.reduce((a, b) => a + b, 0) / nullRates.length;
  return Math.min(avgNullRate * 5, 1); // Scale up and cap at 1
}

// Calculate individual feature scores
const featureScores = {
  baselineDeviation: calculateBaselineDeviationScore(),
  trendVelocity: calculateTrendVelocityScore(),
  historicalPattern: calculateHistoricalPatternScore(),
  statisticalOutlier: calculateStatisticalOutlierScore(),
  nullRate: calculateNullRateScore()
};

// Feature weights (can be tuned based on domain knowledge)
const weights = {
  baselineDeviation: 0.25,
  trendVelocity: 0.20,
  historicalPattern: 0.20,
  statisticalOutlier: 0.20,
  nullRate: 0.15
};

// Calculate weighted anomaly score
let anomalyScore = 0;
for (const feature in featureScores) {
  anomalyScore += featureScores[feature] * weights[feature];
}

// Ensure score is between 0 and 1
anomalyScore = Math.max(0, Math.min(1, anomalyScore));

// Identify top contributing factors
const contributingFactors = Object.entries(featureScores)
  .map(([feature, score]) => ({
    feature,
    score: score,
    weightedContribution: score * weights[feature],
    percentage: (score * weights[feature] / anomalyScore * 100).toFixed(2)
  }))
  .sort((a, b) => b.weightedContribution - a.weightedContribution);

// Determine anomaly severity based on score
let severity = 'low';
if (anomalyScore >= 0.75) {
  severity = 'critical';
} else if (anomalyScore >= 0.5) {
  severity = 'high';
} else if (anomalyScore >= 0.25) {
  severity = 'medium';
}

// Return results
return [{
  json: {
    anomalyScore: parseFloat(anomalyScore.toFixed(4)),
    severity: severity,
    featureScores: featureScores,
    contributingFactors: contributingFactors,
    topContributor: contributingFactors[0]?.feature || 'none',
    weights: weights,
    timestamp: new Date().toISOString(),
    metadata: {
      totalRecords: currentData.totalRecords || 0,
      affectedColumns: currentData.affectedColumns || [],
      anomalyTypes: currentData.anomalyType || []
    }
  }
}];

// Calculate Remediation Success Rate from Historical Data
// Analyzes past remediation attempts to inform current decision making

const historicalData = $('Query Remediation History from PostgreSQL').all();
const currentRemediationPlan = $('AI Remediation Planner Agent').first().json;

// Initialize success rate analysis
const successRateAnalysis = {
  overallSuccessRate: 0,
  actionTypePerformance: {},
  bestPerformingStrategies: [],
  recommendations: [],
  totalAttempts: historicalData.length,
  timestamp: new Date().toISOString()
};

// If no historical data, return default analysis
if (historicalData.length === 0) {
  return [{
    json: {
      ...currentRemediationPlan,
      successRateMetadata: {
        overallSuccessRate: 0,
        confidence: 'low',
        historicalDataPoints: 0,
        recommendation: 'Insufficient historical data - proceeding with AI recommendation'
      }
    }
  }];
}

// Group historical attempts by action type
const actionGroups = {};
let totalSuccesses = 0;

for (const item of historicalData) {
  const data = item.json;
  const actionType = data.action_taken || data.actionTaken || 'unknown';
  const wasSuccessful = data.remediation_successful || data.remediationSuccessful || false;

  if (!actionGroups[actionType]) {
    actionGroups[actionType] = {
      total: 0,
      successful: 0,
      failed: 0,
      avgConfidence: 0,
      severityBreakdown: {}
    };
  }

  actionGroups[actionType].total++;

  if (wasSuccessful) {
    actionGroups[actionType].successful++;
    totalSuccesses++;
  } else {
    actionGroups[actionType].failed++;
  }

  // Track confidence scores
  if (data.classification_confidence || data.confidence) {
    const confidence = data.classification_confidence || data.confidence;
    actionGroups[actionType].avgConfidence += confidence;
  }

  // Track severity breakdown
  const severity = data.severity || 'unknown';
  if (!actionGroups[actionType].severityBreakdown[severity]) {
    actionGroups[actionType].severityBreakdown[severity] = { total: 0, successful: 0 };
  }
  actionGroups[actionType].severityBreakdown[severity].total++;
  if (wasSuccessful) {
    actionGroups[actionType].severityBreakdown[severity].successful++;
  }
}

// Calculate success rates for each action type
for (const [actionType, stats] of Object.entries(actionGroups)) {
  const successRate = (stats.successful / stats.total) * 100;
  const avgConfidence = stats.total > 0 ? stats.avgConfidence / stats.total : 0;

  successRateAnalysis.actionTypePerformance[actionType] = {
    successRate: successRate.toFixed(2),
    totalAttempts: stats.total,
    successful: stats.successful,
    failed: stats.failed,
    avgConfidence: avgConfidence.toFixed(2),
    severityBreakdown: stats.severityBreakdown
  };
}

// Calculate overall success rate
successRateAnalysis.overallSuccessRate = ((totalSuccesses / historicalData.length) * 100).toFixed(2);

// Identify best performing strategies
const sortedActions = Object.entries(successRateAnalysis.actionTypePerformance)
  .sort((a, b) => parseFloat(b[1].successRate) - parseFloat(a[1].successRate))
  .filter(([_, stats]) => stats.totalAttempts >= 3); // Only consider actions with at least 3 attempts

successRateAnalysis.bestPerformingStrategies = sortedActions.slice(0, 3).map(([action, stats]) => ({
  action,
  successRate: stats.successRate,
  totalAttempts: stats.totalAttempts
}));

// Generate recommendations based on current remediation plan
const currentAction = currentRemediationPlan.action;
const currentActionStats = successRateAnalysis.actionTypePerformance[currentAction];

if (currentActionStats) {
  const successRate = parseFloat(currentActionStats.successRate);

  if (successRate >= 80) {
    successRateAnalysis.recommendations.push({
      type: 'high_confidence',
      message: `Action '${currentAction}' has a ${successRate}% historical success rate - proceed with confidence`,
      confidence: 'high'
    });
  } else if (successRate >= 50) {
    successRateAnalysis.recommendations.push({
      type: 'moderate_confidence',
      message: `Action '${currentAction}' has a ${successRate}% historical success rate - proceed with caution`,
      confidence: 'moderate'
    });
  } else {
    successRateAnalysis.recommendations.push({
      type: 'low_confidence',
      message: `Action '${currentAction}' has a ${successRate}% historical success rate - consider alternative approach`,
      confidence: 'low',
      alternatives: successRateAnalysis.bestPerformingStrategies.filter(s => s.action !== currentAction)
    });
  }
} else {
  successRateAnalysis.recommendations.push({
    type: 'no_historical_data',
    message: `No historical data for action '${currentAction}' - proceeding based on AI recommendation`,
    confidence: 'unknown'
  });
}

// Add success rate metadata to remediation plan
const enhancedRemediationPlan = {
  ...currentRemediationPlan,
  successRateMetadata: {
    overallSuccessRate: successRateAnalysis.overallSuccessRate,
    actionSuccessRate: currentActionStats ? currentActionStats.successRate : 'N/A',
    historicalDataPoints: historicalData.length,
    confidence: currentActionStats ? 
      (parseFloat(currentActionStats.successRate) >= 80 ? 'high' : 
       parseFloat(currentActionStats.successRate) >= 50 ? 'moderate' : 'low') : 'unknown',
    recommendations: successRateAnalysis.recommendations,
    bestPerformingStrategies: successRateAnalysis.bestPerformingStrategies,
    fullAnalysis: successRateAnalysis
  }
};

return [{ json: enhancedRemediationPlan }];

