// Data Sampling for Human Review
// Creates a representative sample of data showing the anomaly
// Includes diverse examples, edge cases, and clear context

const items = $input.all();
const anomalyData = $('Run Statistical Quality Checks').first().json;
const classification = $('AI Anomaly Classifier Agent').first().json;
const remediationPlan = $('AI Remediation Planner Agent').first().json;
const originalData = $('Fetch Latest Data from PostgreSQL').all();

// Configuration
const MAX_SAMPLES = 15;
const EDGE_CASE_COUNT = 5;

// Helper function to calculate statistical measures
function getStatistics(values) {
  const sorted = values.filter(v => v !== null && v !== undefined).sort((a, b) => a - b);
  if (sorted.length === 0) return null;

  return {
    min: sorted[0],
    max: sorted[sorted.length - 1],
    median: sorted[Math.floor(sorted.length / 2)],
    mean: sorted.reduce((a, b) => a + b, 0) / sorted.length
  };
}

// Identify affected columns from anomaly data
const affectedColumns = anomalyData.affectedColumns || [];

// Sample selection strategy based on anomaly type
let selectedSamples = [];
const anomalyTypes = anomalyData.anomalyType || [];

if (anomalyTypes.includes('HIGH_NULL_RATE')) {
  // Sample records with nulls in affected columns
  const recordsWithNulls = originalData.filter(item => {
    return affectedColumns.some(col => {
      const value = item.json[col];
      return value === null || value === undefined || value === '';
    });
  });

  // Take diverse samples
  const step = Math.max(1, Math.floor(recordsWithNulls.length / MAX_SAMPLES));
  for (let i = 0; i < Math.min(MAX_SAMPLES, recordsWithNulls.length); i += step) {
    selectedSamples.push({
      record: recordsWithNulls[i].json,
      reason: 'Contains null values in affected columns',
      affectedFields: affectedColumns.filter(col => {
        const value = recordsWithNulls[i].json[col];
        return value === null || value === undefined || value === '';
      })
    });
  }
}

if (anomalyTypes.includes('OUTLIERS_DETECTED')) {
  // Sample records with outlier values
  for (const column of affectedColumns) {
    const values = originalData.map(item => item.json[column]).filter(v => typeof v === 'number');

    if (values.length > 0) {
      const stats = getStatistics(values);
      const sorted = values.sort((a, b) => a - b);
      const q1 = sorted[Math.floor(sorted.length * 0.25)];
      const q3 = sorted[Math.floor(sorted.length * 0.75)];
      const iqr = q3 - q1;
      const lowerBound = q1 - 1.5 * iqr;
      const upperBound = q3 + 1.5 * iqr;

      // Find outlier records
      const outlierRecords = originalData.filter(item => {
        const value = item.json[column];
        return typeof value === 'number' && (value < lowerBound || value > upperBound);
      });

      // Sample extreme outliers (top and bottom)
      const extremeOutliers = outlierRecords
        .sort((a, b) => Math.abs(b.json[column] - stats.median) - Math.abs(a.json[column] - stats.median))
        .slice(0, EDGE_CASE_COUNT);

      extremeOutliers.forEach(item => {
        selectedSamples.push({
          record: item.json,
          reason: `Outlier detected in ${column}`,
          affectedFields: [column],
          outlierDetails: {
            value: item.json[column],
            median: stats.median,
            deviation: Math.abs(item.json[column] - stats.median),
            bounds: { lower: lowerBound, upper: upperBound }
          }
        });
      });
    }
  }
}

if (anomalyTypes.includes('SCHEMA_MISMATCH')) {
  // Sample records showing schema issues
  const schemaMismatch = anomalyData.schemaMismatch || {};

  if (schemaMismatch.missingColumns && schemaMismatch.missingColumns.length > 0) {
    selectedSamples.push({
      record: originalData[0]?.json || {},
      reason: 'Schema mismatch - missing expected columns',
      affectedFields: schemaMismatch.missingColumns,
      schemaIssue: 'Missing columns: ' + schemaMismatch.missingColumns.join(', ')
    });
  }

  if (schemaMismatch.extraColumns && schemaMismatch.extraColumns.length > 0) {
    selectedSamples.push({
      record: originalData[0]?.json || {},
      reason: 'Schema mismatch - unexpected columns present',
      affectedFields: schemaMismatch.extraColumns,
      schemaIssue: 'Extra columns: ' + schemaMismatch.extraColumns.join(', ')
    });
  }
}

// If no specific samples selected, take random diverse samples
if (selectedSamples.length === 0 && originalData.length > 0) {
  const step = Math.max(1, Math.floor(originalData.length / MAX_SAMPLES));
  for (let i = 0; i < Math.min(MAX_SAMPLES, originalData.length); i += step) {
    selectedSamples.push({
      record: originalData[i].json,
      reason: 'Representative sample from dataset',
      affectedFields: affectedColumns
    });
  }
}

// Limit to MAX_SAMPLES
selectedSamples = selectedSamples.slice(0, MAX_SAMPLES);

// Create formatted output for human review
const reviewReport = {
  summary: {
    anomalyType: classification.classification || anomalyTypes.join(', '),
    severity: classification.severity || 'unknown',
    confidence: classification.confidence || 0,
    totalRecords: originalData.length,
    samplesIncluded: selectedSamples.length,
    affectedColumns: affectedColumns,
    timestamp: new Date().toISOString()
  },

  context: {
    explanation: classification.explanation || 'No explanation provided',
    attemptedRemediation: remediationPlan.action || 'unknown',
    remediationReasoning: remediationPlan.reasoning || 'No reasoning provided'
  },

  statistics: anomalyData.statistics || {},

  dataSamples: selectedSamples.map((sample, idx) => ({
    sampleNumber: idx + 1,
    reason: sample.reason,
    affectedFields: sample.affectedFields,
    outlierDetails: sample.outlierDetails || null,
    schemaIssue: sample.schemaIssue || null,
    data: sample.record
  })),

  recommendations: [
    'Review the data samples above to understand the anomaly pattern',
    'Check if the affected columns require schema changes or validation rules',
    'Verify if the anomaly is due to upstream data source issues',
    'Consider updating quality check thresholds if this is expected behavior',
    'Implement additional validation rules to prevent similar issues'
  ]
};

return [{ json: reviewReport }];
